package notification.core.template;import lombok.RequiredArgsConstructor;import notification.core.NotificationType;import notification.core.exception.TemplateNotFoundException;import org.springframework.stereotype.Component;import java.util.List;import java.util.Optional;@Component@RequiredArgsConstructorpublic class TemplateResolver {    private final List<TemplateProvider> providers;    public Template resolve(NotificationType type, String language, String version, String variant) {        for (TemplateProvider provider : providers) {            Optional<Template> template = provider.find(type, language, version, variant);            if (template.isPresent()) return template.get();        }        throw new TemplateNotFoundException(type, language, version, variant);    }}